/** Production optical proxy and export-video staging, with the same final
 * encoder for the three portrait runs. Inputs are generated by run-product. */
import assert from 'node:assert/strict';
import {closeSync, mkdirSync, openSync, statSync} from 'node:fs';
import {writeFile} from 'node:fs/promises';
import path from 'node:path';
import {prepareOpticalProxy, renderOpticalProxy} from '../../packages/business/src/timeline-processing/optical.ts';
import {prepareSpeedExportVideo} from '../../packages/business/src/timeline-speed-export-video.ts';
import {compileTimeMap, initialTimeMap} from '../../packages/contracts/src/timeline-time-map.ts';
import {runFfmpeg} from './samples.mjs';

const [mode, sourcePath, sourceFrameText, work, delivery, sceneCutText] = process.argv.slice(2);
const sourceFrames = Number(sourceFrameText);
const fps = {fpsNumerator: 30, fpsDenominator: 1};
const boundary = frames => ({kind: 'rational', numerator: String(frames), denominator: '1'});
const basis = {profile: 'timeline-speed-v1', sourceFps: fps, outputFps: fps,
  sourceRange: {start: boundary(0), end: boundary(sourceFrames)},
  speed: {kind: 'constant', rate: {numerator: 1, denominator: 4}}};
const root = compileTimeMap(basis);
assert.ok(root.ok, JSON.stringify(root));
const plan = initialTimeMap(root.value);
const timing = {profile: 'timeline-speed-v1', basis, outputWindow: plan.outputWindow,
  view: {direction: 'forward', loTime: {anchor: 'start', offsetOutputFrames: 0},
    hiTime: {anchor: 'end', offsetOutputFrames: 0}}, interpolation: mode, pitchShift: false};
const signal = new AbortController().signal;
const syntheticScope = {signal, beforeEffect() {}};
let optical;
let maxPhaseErrorFrames;
if (mode === 'optical') {
  const stagingDirectory = path.join(work, 'proxy');
  mkdirSync(stagingDirectory, {mode: 0o700});
  const input = {sourcePath, mapHash: plan.root.mapHash, window: {timing, sourceFrames, beforeFrames: 0, afterFrames: 0},
    sceneCuts: async () => sceneCutText === undefined ? [] : [Number(sceneCutText)]};
  const prepared = await prepareOpticalProxy(input, syntheticScope);
  maxPhaseErrorFrames = prepared.profile.maxPhaseErrorFrames;
  const ready = await renderOpticalProxy(input, prepared, {...syntheticScope, stagingDirectory,
    frameCount: prepared.profile.frameCount, sampleCount: 0});
  optical = {file: path.join(stagingDirectory, 'proxy.mkv'),
    firstOutputFrame: ready.firstOutputFrame, frameCount: ready.frameCount};
}
const stage = await prepareSpeedExportVideo({
  source: {path: sourcePath}, plan, timing, optical, firstOutputFrame: 0, ...syntheticScope,
  file: path.join(work, 'stage.mkv'), scriptFile: path.join(work, 'video.filter'),
  reserve(file) {closeSync(openSync(file, 'wx', 0o600));},
  writeOwnedFile: (file, bytes) => writeFile(file, bytes, {flag: 'wx', mode: 0o600}),
});
assert.equal(stage.frameCount, sourceFrames * 4);
assert.equal(stage.path, mode === 'off' ? 'cfr' : mode);
assert.deepEqual(stage.inputArgs, []);
const file = path.join(work, 'result.mkv');
if (delivery === 'x264') {
  runFfmpeg(process.env.MIOON_FFMPEG_PATH, ['-filter_threads', '1', '-i', stage.file, '-an',
    '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '23', '-threads', '2', '-bf', '0', '-g', '60',
    '-pix_fmt', 'yuv420p', '-r', '30', file]);
}
console.log(JSON.stringify({path: stage.path, stageBytes: stage.bytes, maxPhaseErrorFrames,
  outputBytes: statSync(delivery === 'x264' ? file : stage.file).size}));
